/// Hosted POS API routes, relative to [prefix] on the configured API origin.
///
/// Examples below describe JSON request bodies unless marked as query examples.
/// IDs and credentials are illustrative; proofs and signatures are generated by
/// the app. Authenticated calls send `Authorization: Bearer <token>`. Calls with
/// a command ID also send `Idempotency-Key: <command-id>` for safe retries.
/// Money amounts use integer currency units (USD cents or whole KHR).
/// Use the `...For` helpers or [saleById] to fill parameterized route constants.
abstract final class ApiEndpoint {
  /// Base path prepended by PosApi; the API origin is configured per register.
  static const prefix = '/api/integrations/pos/v1';

  /// POST: Sign in with an email or a previously resolved staff username.
  /// `username` is optional; the proof is 64 lowercase hexadecimal characters.
  ///
  /// ```json
  /// {"business_slug":"demo","email":"owner@example.com",
  ///  "username":"owner","password_proof":"<derived-password-proof>",
  ///  "auth_version":"client-pbkdf2-sha256-v1"}
  /// ```
  static const login = '/auth/login';

  /// POST: Resolve a staff username using an owner or manager session.
  ///
  /// ```json
  /// {"username":"cashier"}
  /// ```
  static const resolveUsername = '/auth/resolve-username';

  /// POST: Renew a device session using a signed proof; no bearer is required.
  /// `issued_at` is Unix seconds; nonce/signature are 64/128 hex characters.
  ///
  /// ```json
  /// {"credential_id":"credential-id","issued_at":1794963600,
  ///  "nonce":"<random-nonce>","signature":"<ed25519-signature>"}
  /// ```
  static const deviceSession = '/auth/device-session';

  /// GET: List profiles available to the signed-in operator. No request body.
  /// Query example: `{"page":"1","page_size":"100"}`.
  static const profiles = '/profiles';

  /// POST: Exchange a discovery token for a profile session.
  ///
  /// ```json
  /// {"profile_id":"profile-id"}
  /// ```
  static const sessions = '/sessions';

  /// DELETE: Sign out the current session. Payload: none (no request body).
  static const currentSession = '$sessions/current';

  /// GET: Read business, operator, profile, permissions, and operating context.
  /// Payload: none (no query parameters or request body).
  static const context = '/context';

  /// GET: Read products and the eligible menu/category hierarchy. No body.
  /// Query example: `{"menu_id":"menu-id","page":"1","page_size":"100"}`.
  /// menu_id scopes a menu profile to that menu and its descendants; omit it
  /// for category profiles or when no default_menu_id is configured.
  /// Hierarchy nodes include image_url when a menu/category has a photo.
  static const catalog = '/catalog';

  /// GET: List tables and their open bills for this profile. No request body.
  /// Query example: `{"page":"1","page_size":"100"}`.
  static const tables = '/tables';

  /// GET: List customers. POST: Create a customer using an idempotency key.
  static const customers = '/customers';

  /// GET: Read a customer. PATCH and DELETE use idempotency keys.
  static String customerFor(String id) => '$customers/$id';

  /// GET: Read a customer's uploaded photo using a POS profile session.
  static String customerPhotoFor(String id) => '${customerFor(id)}/photo';

  /// GET: List customer groups available to the register.
  static const customerGroups = '/customer-groups';

  /// GET: List staff and POS usernames using a manager session. No body.
  /// Query example: `{"page":"1","page_size":"100"}`.
  static const staff = '/staff';

  /// PUT: Set a staff POS username; send null to clear it. Uses idempotency.
  /// Path example: `/staff/staff-id/username`.
  ///
  /// ```json
  /// {"username":"cashier"}
  /// ```
  static const staffUsername = '$staff/{id}/username';

  static String staffUsernameFor(String id) =>
      staffUsername.replaceFirst('{id}', id);

  /// POST: Enroll this installation's Ed25519 public key with a password session.
  /// `public_key` is the 32-byte public key encoded as 64 hex characters.
  ///
  /// ```json
  /// {"device_id":"installation-id","device_name":"eMenu POS windows",
  ///  "public_key":"<ed25519-public-key>"}
  /// ```
  static const devices = '/devices';

  /// Claim or release branch authority using the owner's enrolled device.
  /// POST body: `{}`. DELETE body example:
  ///
  /// ```json
  /// {"epoch":"authority-epoch","last_sequence":12}
  /// ```
  static const storeAuthority = '/store-authority';

  /// POST: Upload a saved store event in sequence. Uses the event's command ID
  /// as the idempotency key and its original operator/profile device session.
  /// The payload depends on kind; this example opens a working day.
  ///
  /// ```json
  /// {"epoch":"authority-epoch","sequence":1,"kind":"open_day",
  ///  "resource_id":"day-id","profile_id":"profile-id",
  ///  "occurred_at":"2026-11-18T01:00:00.000Z",
  ///  "settings":{"working_day_enabled":true,"cashier_shift_enabled":true},
  ///  "payload":{}}
  /// ```
  static const storeOperations = '/store-operations';

  /// POST: Recover an event after its original operator loses access.
  /// Uses the owner's device session and the original event's idempotency key.
  /// `operation` is the complete original [storeOperations] envelope.
  ///
  /// ```json
  /// {"profile_id":"profile-id","operator_id":"operator-id",
  ///  "reason":"Operator access removed",
  ///  "operation":{"epoch":"authority-epoch","sequence":1,
  ///   "kind":"open_day","resource_id":"day-id","profile_id":"profile-id",
  ///   "occurred_at":"2026-11-18T01:00:00.000Z",
  ///   "settings":{"working_day_enabled":true,"cashier_shift_enabled":true},
  ///   "payload":{}}}
  /// ```
  static const recoverStoreOperations = '$storeOperations/recover';

  /// POST: Create a server-priced sale draft. Uses idempotency.
  /// Optional `posting_date` (YYYY-MM-DD) is editable without cashier shifts.
  /// Guest cover without a table requires prompt_guest_cover in the profile.
  /// Day/shift IDs in expected_context are null when those features are disabled.
  ///
  /// ```json
  /// {"table_id":null,"guest_cover":null,"customer_id":null,
  ///  "lines":[{"product_id":"coffee-id","portion_id":null,
  ///            "modifier_ids":[],"quantity":1}],
  ///  "expected_context":{"business_date":"2026-11-18",
  ///                      "working_day_id":"day-id","shift_id":"shift-id"}}
  /// ```
  static const sales = '/sales';

  /// GET: Read a saved sale, its payments, and reversal links. No body or query.
  /// Path example: `/sales/sale-id`.
  static const sale = '$sales/{id}';

  static String saleById(String id) => sale.replaceFirst('{id}', id);

  /// POST: Fully reverse a sale. Uses idempotency.
  /// Path example: `/sales/sale-id/reverse`.
  ///
  /// ```json
  /// {"reason":"Customer refund","expected_total_minor":500,
  ///  "expected_context":{"business_date":"2026-11-18",
  ///                      "working_day_id":"day-id","shift_id":"shift-id"}}
  /// ```
  static const reverseSale = '$sale/reverse';

  static String reverseSaleFor(String id) =>
      reverseSale.replaceFirst('{id}', id);

  /// POST: Settle the saved draft revision with payments. Uses idempotency.
  /// Optional `posting_date` preserves the bill's chosen date without shifts;
  /// expected_context always describes the current operating day and shift.
  /// Path example: `/sales/sale-id/checkout`.
  ///
  /// ```json
  /// {"revision":1,"expected_total_minor":500,
  ///  "expected_context":{"business_date":"2026-11-18",
  ///                      "working_day_id":"day-id","shift_id":"shift-id"},
  ///  "payments":[{"payment_type_id":"cash-id","currency":"USD",
  ///               "amount_minor":500}]}
  /// ```
  static const checkoutSale = '$sale/checkout';

  static String checkoutSaleFor(String id) =>
      checkoutSale.replaceFirst('{id}', id);

  /// POST: Open the branch's working day. Body: `{}`. Uses idempotency.
  static const workingDays = '/working-days';

  static String workingDaySummaryFor(String id) => '$workingDays/$id/summary';

  /// POST: Close a working day after its activity is resolved.
  /// Path example: `/working-days/day-id/close`. Body: `{}`. Uses idempotency.
  static const closeWorkingDay = '$workingDays/{id}/close';

  static String closeWorkingDayFor(String id) =>
      closeWorkingDay.replaceFirst('{id}', id);

  /// POST: Open a cashier shift with opening balances. Uses idempotency.
  /// `day_id` is used locally and removed before the hosted API request.
  ///
  /// ```json
  /// {"opening_cash":[{"payment_type_id":"cash-id","currency":"USD",
  ///                   "amount_minor":2000}]}
  /// ```
  static const cashierShifts = '/cashier-shifts';

  static String cashierShiftSummaryFor(String id) =>
      '$cashierShifts/$id/summary';
  static String reopenCashierShiftFor(String id) => '$cashierShifts/$id/reopen';
  static String commandStatusFor(String id) => '/commands/$id';

  /// GET: Preview expected drawer amounts and activity_revision for closing.
  /// Path example: `/cashier-shifts/shift-id/reconciliation`. Payload: none.
  static const cashierShiftReconciliation =
      '$cashierShifts/{id}/reconciliation';

  static String cashierShiftReconciliationFor(String id) =>
      cashierShiftReconciliation.replaceFirst('{id}', id);

  /// POST: Close a shift using its latest reconciliation. Uses idempotency.
  /// Path example: `/cashier-shifts/shift-id/close`.
  /// Include a count for every payment type/currency in the preview.
  ///
  /// ```json
  /// {"activity_revision":3,
  ///  "counts":[{"payment_type_id":"cash-id","currency":"USD",
  ///             "declared_minor":2500}]}
  /// ```
  static const closeCashierShift = '$cashierShifts/{id}/close';

  static String closeCashierShiftFor(String id) =>
      closeCashierShift.replaceFirst('{id}', id);

  /// POST: Record cash in or cash out of a drawer. Uses idempotency.
  /// Path example: `/cashier-shifts/shift-id/cash-floats`.
  ///
  /// ```json
  /// {"kind":"cash_in","payment_type_id":"cash-id","currency":"USD",
  ///  "amount_minor":1000,"reason":"Extra change"}
  /// ```
  static const cashierShiftCashFloats = '$cashierShifts/{id}/cash-floats';

  static String cashierShiftCashFloatsFor(String id) =>
      cashierShiftCashFloats.replaceFirst('{id}', id);
}

/// Local store API routes on the paired register's certificate-pinned HTTPS
/// origin. These constants include [prefix]; StoreClient sends JSON POSTs.
/// Authorization uses the invitation, device, or staff credential noted below.
abstract final class StoreApiEndpoint {
  /// Base path shared by the local store client and host.
  static const prefix = '/store/v1';

  static const shiftManagement = '$prefix/shift-management';

  /// POST: Pair a till using the invitation secret as bearer credential.
  ///
  /// ```json
  /// {"attempt_id":"attempt-id","label":"Front till","pos_token":"<token>"}
  /// ```
  static const pair = '$prefix/pair';

  /// POST: Enroll an operator using the paired device credential as bearer.
  ///
  /// ```json
  /// {"pos_token":"<operator-profile-token>"}
  /// ```
  static const enroll = '$prefix/enroll';

  /// POST: Read snapshot, held bills, and sales using a staff credential.
  /// Send null for snapshot_version when no snapshot is cached.
  /// Set reload_menu to fetch fresh cloud profile configuration and catalog.
  /// Successful reloads return a full snapshot and menu_reloaded: true.
  ///
  /// ```json
  /// {"snapshot_version":null,"reload_menu":true}
  /// ```
  static const state = '$prefix/state';

  /// POST: Read local history, a server page, or a server sale detail as staff.
  static const salesHistory = '$prefix/sales-history';

  /// POST: Load customer groups or forward a customer write to the hosted API.
  static const customerDirectory = '$prefix/customer-directory';

  /// POST: Execute a RegisterAction using a staff credential.
  /// Reuse id when retrying; action and payload depend on the operation.
  ///
  /// ```json
  /// {"id":"command-id","action":"openShift",
  ///  "payload":{"day_id":"day-id","opening_cash":[
  ///   {"payment_type_id":"cash-id","currency":"USD","amount_minor":2000}]}}
  /// ```
  static const command = '$prefix/command';
}

/// Admin API route used by the Worker smoke test to update its fixture grants.
/// This full path uses an admin bearer token rather than a POS profile token.
abstract final class AdminApiEndpoint {
  /// PUT: Replace explicit staff grants for a profile.
  /// Path example: `/api/admin/pos/profiles/profile-id/grants`.
  /// Body example: `{"user_ids":[]}` removes the fixture's staff grants.
  static const profileGrants = '/api/admin/pos/profiles/{id}/grants';

  static String profileGrantsFor(String id) =>
      profileGrants.replaceFirst('{id}', id);
}
